  function normalizeIntervals(intervals) {
    const valid = intervals.filter(([start, end]) => start < end);
    if (valid.length === 0) return [];

    valid.sort((a, b) => a[0] - b[0] || a[1] - b[1]);

    const merged = [valid[0]];
    for (let i = 1; i < valid.length; i++) {
      const last = merged[merged.length - 1];
      const curr = valid[i];

      if (curr[0] <= last[1]) {
        last[1] = Math.max(last[1], curr[1]);
      } else {
        merged.push(curr);
      }
    }

    return merged;
  }

  function subtractIntervals(base, toRemove) {
    if (base.length === 0 || toRemove.length === 0) return base;

    let result = [];

    for (const [start, end] of base) {
      let segments = [[start, end]];

      for (const [remStart, remEnd] of toRemove) {
        let newSegments = [];

        for (const [segStart, segEnd] of segments) {
          if (remEnd <= segStart || remStart >= segEnd) {
            newSegments.push([segStart, segEnd]);
          } else {
            if (segStart < remStart) {
              newSegments.push([segStart, remStart]);
            }
            if (segEnd > remEnd) {
              newSegments.push([remEnd, segEnd]);
            }
          }
        }

        segments = newSegments;
      }

      result.push(...segments);
    }

    return normalizeIntervals(result);
  }

  const addNormalized = normalizeIntervals(add);
  const removeNormalized = normalizeIntervals(remove);

  return subtractIntervals(addNormalized, removeNormalized);
}
```

